import{_ as o,o as i,c as a,a2 as r}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Runbook: backup e restore (PostgreSQL + bucket S3)","description":"","frontmatter":{},"headers":[],"relativePath":"runbook/backup-restore.md","filePath":"runbook/backup-restore.md"}'),t={name:"runbook/backup-restore.md"};function n(l,e,c,s,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="runbook-backup-e-restore-postgresql-bucket-s3" tabindex="-1">Runbook: backup e restore (PostgreSQL + bucket S3) <a class="header-anchor" href="#runbook-backup-e-restore-postgresql-bucket-s3" aria-label="Permalink to &quot;Runbook: backup e restore (PostgreSQL + bucket S3)&quot;">​</a></h1><p>Ambito: Cloud Service Clarae notanda (modular monolith) con PostgreSQL e uno store S3-compatibile per i blob. Requisito di riferimento: Appendice A, &quot;Affidabilità dati: RPO ≤ 5 min (PITR PG, versioning bucket)&quot;. Il procedimento qui descritto è provato da <code>scripts/chaos/restore-drill.sh</code> su container usa e getta (esito in fondo).</p><h2 id="_1-che-cosa-si-protegge" tabindex="-1">1. Che cosa si protegge <a class="header-anchor" href="#_1-che-cosa-si-protegge" aria-label="Permalink to &quot;1. Che cosa si protegge&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dato</th><th>Dove</th><th>Proprietà</th><th>Come si protegge</th></tr></thead><tbody><tr><td>Stato (utenti, vault, file, revisioni, changelog <code>seq</code>, share, quote, config)</td><td>PostgreSQL</td><td>Fonte di verità; <code>seq</code> per vault monotono</td><td>Base backup + archiviazione WAL continua (PITR); dump logico come seconda rete</td></tr><tr><td>Contenuto dei file</td><td>Bucket S3 <code>clarae-blobs</code></td><td>Blob <strong>content-addressed</strong> (SHA-256) e immutabili; una chiave non cambia mai contenuto</td><td>Versioning del bucket + lifecycle sulle versioni non correnti</td></tr><tr><td>Export ZIP</td><td>Bucket <code>clarae-exports</code></td><td>Temporanei (scadono)</td><td>Nessun backup necessario</td></tr><tr><td>Identità</td><td>Keycloak (DB proprio)</td><td>Fuori dal perimetro di questo runbook</td><td>Backup del DB di Keycloak e export del realm, stessa disciplina</td></tr></tbody></table><p>I vault privati sono E2EE: backup e restore contengono solo testo cifrato. Nessuna chiave è nel backup: la perdita di passphrase e recovery key resta non recuperabile (D-02).</p><h2 id="_2-obiettivi-rpo-rto" tabindex="-1">2. Obiettivi (RPO / RTO) <a class="header-anchor" href="#_2-obiettivi-rpo-rto" aria-label="Permalink to &quot;2. Obiettivi (RPO / RTO)&quot;">​</a></h2><ul><li><strong>RPO ≤ 5 minuti</strong> (Appendice A). Si ottiene con WAL archiviati di continuo e <code>archive_timeout</code> ≤ 60 s (l&#39;ultimo segmento parziale viene spedito entro 60 s); i blob non hanno finestra di perdita propria perché l&#39;upload precede il commit del riferimento in DB e il bucket è durevole. Il valore da monitorare è l&#39;età dell&#39;ultimo WAL archiviato (alert se &gt; 3 min).</li><li><strong>RTO</strong>: la specifica non ne fissa uno. Obiettivo proposto: <strong>≤ 1 ora</strong> per un database da 100 GB con base backup nello stesso datacenter; è dominato dalla copia del base backup e dal replay dei WAL, non dall&#39;applicazione. Il drill misura solo il costo fisso (vedi §7): va ripetuto con un dataset realistico prima del rilascio 1.0.</li></ul><h2 id="_3-configurazione-del-backup" tabindex="-1">3. Configurazione del backup <a class="header-anchor" href="#_3-configurazione-del-backup" aria-label="Permalink to &quot;3. Configurazione del backup&quot;">​</a></h2><h3 id="_3-1-postgresql-self-managed" tabindex="-1">3.1 PostgreSQL (self-managed) <a class="header-anchor" href="#_3-1-postgresql-self-managed" aria-label="Permalink to &quot;3.1 PostgreSQL (self-managed)&quot;">​</a></h3><p>Parametri sul server (verificati dal drill):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wal_level = replica</span></span>
<span class="line"><span>archive_mode = on</span></span>
<span class="line"><span>archive_command = &#39;test ! -f /wal-archive/%f &amp;&amp; cp %p /wal-archive/%f&#39;   # in produzione: pgBackRest / WAL-G verso S3 o NFS, mai sullo stesso disco del DB</span></span>
<span class="line"><span>archive_timeout = 60</span></span></code></pre></div><ul><li><strong>Base backup</strong>: <code>pg_basebackup -D &lt;dir&gt; -Ft -z -X stream -c fast</code> (giornaliero; ritenzione ≥ finestra PITR desiderata + 1 base backup). Sono equivalenti <code>pgBackRest backup</code> o <code>wal-g backup-push</code>, preferibili in produzione (incrementali, verifica, ritenzione).</li><li><strong>Dump logico</strong> (rete di sicurezza, non PITR): <code>pg_dump -Fc -f clarae.dump clarae</code>, settimanale. Serve per migrare/ispezionare, non per rispettare l&#39;RPO.</li><li><strong>Verifica</strong>: ogni base backup va ripristinato da un job periodico (è ciò che fa il drill); un backup mai ripristinato non è un backup.</li></ul><h3 id="_3-2-postgresql-gestito" tabindex="-1">3.2 PostgreSQL gestito <a class="header-anchor" href="#_3-2-postgresql-gestito" aria-label="Permalink to &quot;3.2 PostgreSQL gestito&quot;">​</a></h3><p>Usare il PITR del servizio (RDS/Aurora, Cloud SQL, Azure Flexible Server, CloudNativePG con barman): abilitare la ritenzione dei backup ≥ 7 giorni e il PITR continuo; il ripristino crea una nuova istanza al timestamp scelto, poi si ripunta <code>DATABASE_URL</code> (stessi passi di §5 dal punto 3).</p><h3 id="_3-3-bucket-s3" tabindex="-1">3.3 Bucket S3 <a class="header-anchor" href="#_3-3-bucket-s3" aria-label="Permalink to &quot;3.3 Bucket S3&quot;">​</a></h3><ul><li><strong>Versioning attivo</strong> su <code>clarae-blobs</code> (<code>PutBucketVersioning</code> = Enabled). Una cancellazione crea un <em>delete marker</em>, una sovrascrittura una nuova versione: entrambe reversibili.</li><li><strong>Lifecycle</strong>: scadenza delle sole versioni non correnti dopo N giorni, con <strong>N ≥ finestra PITR</strong> (consigliato 30), così un DB ripristinato a T trova ancora i blob che il GC ha tolto dopo T. Non impostare mai scadenza sulla versione corrente.</li><li>Facoltativi: replica cross-region, Object Lock in modalità governance.</li><li><strong>Supporto per backend</strong>: il drill sonda lo store (<code>drilltool s3 probe</code>: due put, una delete, elenco delle versioni). <strong>RustFS (<code>rustfs/rustfs:latest</code>, lo store di sviluppo) supporta versioning, delete marker, ripristino di versione e regole lifecycle</strong> (esito del 2026-10-27); lo script ripiega su MinIO solo se la sonda fallisce. Per la produzione usare uno store che offra le stesse funzioni (AWS S3, MinIO, Ceph RGW) e rieseguire la sonda sul backend scelto.</li></ul><h2 id="_4-perche-l-ordine-conta-db-prima-poi-i-blob" tabindex="-1">4. Perché l&#39;ordine conta (DB prima, poi i blob) <a class="header-anchor" href="#_4-perche-l-ordine-conta-db-prima-poi-i-blob" aria-label="Permalink to &quot;4. Perché l&#39;ordine conta (DB prima, poi i blob)&quot;">​</a></h2><p>I blob sono immutabili e il DB li referenzia per hash. Ripristinando il DB a T:</p><ol><li>il DB referenzia solo blob esistenti a T, quindi ciò che manca nel bucket può essere solo qualcosa <strong>cancellato dopo T</strong> (GC, errore operatore);</li><li>i blob creati dopo T restano nel bucket senza riga in DB: orfani innocui (nessuno li referenzia, occupano solo spazio; non vengono rimossi dal GC perché è guidato dalla tabella <code>blobs</code>);</li><li>il bucket non va mai riportato indietro nel tempo insieme al DB: è inutile e rischioso.</li></ol><p>Perciò: si ripristina <strong>prima il DB</strong>, poi si <strong>verifica la coerenza DB↔bucket</strong> e si recuperano dalle versioni eventuali oggetti mancanti.</p><h2 id="_5-procedura-di-restore-pitr" tabindex="-1">5. Procedura di restore (PITR) <a class="header-anchor" href="#_5-procedura-di-restore-pitr" aria-label="Permalink to &quot;5. Procedura di restore (PITR)&quot;">​</a></h2><p>Precondizione: stabilire il timestamp target <strong>T</strong> (UTC, es. l&#39;ultimo istante prima dell&#39;incidente) dal log di audit o dai log applicativi.</p><ol><li><strong>Fermare il traffico e i job</strong>: <code>kubectl scale deploy/&lt;rel&gt;-clarae-api deploy/&lt;rel&gt;-clarae-worker --replicas=0</code> (il worker esegue GC blob e manutenzione: non deve girare con DB e bucket in stati diversi).</li><li><strong>Ripristinare PostgreSQL a T</strong><ul><li>Preparare un data directory vuoto, estrarre <code>base.tar.gz</code> e <code>pg_wal.tar.gz</code> del base backup scelto (anteriore a T) in <code>PGDATA</code> e <code>PGDATA/pg_wal</code>;</li><li>creare <code>recovery.signal</code>; in <code>postgresql.auto.conf</code>: <code>restore_command = &#39;cp /wal-archive/%f %p&#39;</code>, <code>recovery_target_time = &#39;&lt;T&gt;&#39;</code>, <code>recovery_target_action = &#39;promote&#39;</code>;</li><li>impostare proprietario <code>postgres</code> e modo <code>0700</code>, avviare. Il server riproduce i WAL fino a T e si promuove (nuova timeline). Il log riporta <code>recovery stopping before commit of transaction …, time &lt;T&gt;</code>.</li><li>Attenzione: il restore fallisce con &quot;recovery ended before configured recovery target&quot; se non esistono WAL <strong>successivi</strong> a T: forzare <code>SELECT pg_switch_wal()</code> prima dell&#39;incidente non è possibile a posteriori, quindi usare un T anteriore all&#39;ultimo WAL archiviato.</li></ul></li><li><strong>Verificare il DB</strong>: <code>SELECT pg_is_in_recovery()</code> deve dare <code>f</code>; conteggi di <code>vaults</code>, <code>files</code>, <code>file_revisions</code>; <code>max(last_seq)</code> per vault coerente con <code>max(seq)</code> di <code>file_revisions</code>.</li><li><strong>Verificare i blob</strong> (coerenza DB↔bucket): per ogni riga di <code>blobs</code> con <code>ref_count &gt; 0</code>, l&#39;oggetto <code>blobs/&lt;hh&gt;/&lt;hash&gt;</code> esiste con la dimensione attesa. Lo fa <code>services/cloud/test/drilltool verify-blobs</code>; in alternativa <code>psql -Atc &quot;select storage_key,size from blobs where ref_count&gt;0&quot;</code> confrontato con <code>aws s3api head-object</code>. Per ogni oggetto mancante o con dimensione diversa: <ul><li>cancellato: rimuovere il <em>delete marker</em> (<code>aws s3api delete-object --version-id &lt;id-del-marker&gt;</code>);</li><li>sovrascritto: rimuovere la versione corrente errata (la precedente torna corrente) o copiare la versione buona sopra la corrente;</li><li>nessuna versione disponibile: il blob è perso; i file che lo referenziano vanno cercati nei client (che mantengono la copia locale) e ricaricati.</li></ul></li><li><strong>Riavviare</strong> API e worker (<code>--replicas</code> originali). Il job di <strong>manutenzione</strong> (parte 30 s dopo l&#39;avvio del worker, poi ogni 24 h) esegue <code>ReconcileUsage</code> e <code>ReconcileBlobRefs</code>: ricalcola contatori di quota e <code>ref_count</code> dal contenuto reale del DB e corregge la deriva; controllare nei log <code>usage drift corrected</code> / <code>blob ref count corrected</code> (attesi dopo un PITR) e l&#39;assenza di <code>job failed</code>.</li><li><strong>Client</strong> (<a href="./../adr/0046-bootstrap-server-indietro.html">ADR-0046</a>): i dispositivi che avevano già sincronizzato oltre T hanno un cursore <strong>maggiore</strong> dell&#39;<code>last_seq</code> del server, oppure, se un altro dispositivo ha già ricaricato qualcosa, un cursore il cui <code>seq</code> è stato riusato da un cambiamento diverso (il client invia con il cursore anche l&#39;id del cambiamento, <code>since_id</code>). In entrambi i casi il server risponde <code>410 CURSOR_EXPIRED</code> con <code>last_seq</code> e il client esegue il bootstrap da <code>/tree</code> in modalità <em>reconcile-upload</em>: le revisioni più recenti di quelle del server vengono ripubblicate come nuove revisioni, i file che il server non elenca più vengono ricaricati (non cestinati) e ciò che il server ha di più nuovo si applica come sempre; prima di ogni sovrascrittura il client salva la versione locale in <em>File recovery</em>. Il primo dispositivo che si collega ripubblica, gli altri ritrovano lo stesso contenuto o passano dal merge. Conseguenza voluta (D-04): un file cancellato dopo T può ricomparire. Informare gli utenti di controllare i file ricomparsi e, in caso di dubbi, <em>File recovery</em>. I desktop fino alla 1.3.1 non inviano <code>since_id</code> e reagiscono al bootstrap come prima (i file che il server ha perso finiscono nel cestino locale <code>.trash/</code>, mai cancellati definitivamente): aggiornarli prima di un ripristino, se possibile.</li><li><strong>Verifiche finali</strong> (checklist): <code>/readyz</code> verde; login e <code>GET /me</code>; per un vault campione: <code>tree</code>, download di un blob con controllo SHA-256, <code>changes?since=0</code> con <code>seq</code> contigui; conteggio file e quota in Web UI; audit log: registrare l&#39;evento di restore con T e operatore.</li></ol><h2 id="_6-ripristino-puntuale-di-un-oggetto-del-bucket-senza-toccare-il-db" tabindex="-1">6. Ripristino puntuale di un oggetto del bucket (senza toccare il DB) <a class="header-anchor" href="#_6-ripristino-puntuale-di-un-oggetto-del-bucket-senza-toccare-il-db" aria-label="Permalink to &quot;6. Ripristino puntuale di un oggetto del bucket (senza toccare il DB)&quot;">​</a></h2><p>Caso: un blob è stato cancellato o sovrascritto, il DB è sano.</p><ol><li>Individuare la chiave: <code>blobs/&lt;primi 2 caratteri dell&#39;hash&gt;/&lt;hash&gt;</code>.</li><li><code>aws s3api list-object-versions --bucket clarae-blobs --prefix &lt;chiave&gt;</code>: cercare delete marker (<code>IsLatest: true</code>) o la versione precedente.</li><li>Ripristinare come al punto 4 di §5 e rieseguire <code>verify-blobs</code>.</li><li>Nota: il server <strong>non</strong> verifica l&#39;hash in lettura; è il client a farlo (<code>fetch</code> scarta il contenuto che non corrisponde al digest). Un oggetto corrotto in silenzio si manifesta come errore di sincronizzazione del client, non come errore del server.</li></ol><h2 id="_7-prova-eseguita-restore-drill" tabindex="-1">7. Prova eseguita (restore drill) <a class="header-anchor" href="#_7-prova-eseguita-restore-drill" aria-label="Permalink to &quot;7. Prova eseguita (restore drill)&quot;">​</a></h2><p><code>scripts/chaos/restore-drill.sh</code> (container <code>clarae-chaos-drill-*</code>, rimossi a fine esecuzione; report in <code>.dev/chaos/drill-*/report.md</code>):</p><ol><li>PostgreSQL 17 con archiviazione WAL + store S3 (RustFS, con ripiego su MinIO se manca il versioning), cloud reale come processo;</li><li>dati creati via API (lotto a: 30 file, alcuni da ~300 KB), base backup + dump logico, versioning e lifecycle sul bucket;</li><li>lotto b (20 file), punto T, poi &quot;incidente&quot;: b cancellato via API e lotto c creato dopo T;</li><li>guasti sul bucket: oggetto cancellato e oggetto sovrascritto, rilevati da <code>verify-blobs</code> e riparati dalle versioni;</li><li><strong>distruzione del database</strong> (container + volume), <strong>PITR a T</strong>, riavvio del cloud, job di manutenzione;</li><li>verifica: file a+b presenti e c assente, ogni blob scaricato con digest corretto, changelog <code>1..N</code> contiguo, coerenza DB↔bucket, cursore avanti rifiutato con <code>CURSOR_EXPIRED</code>, nuove scritture accettate; ripristino del dump logico in un DB di prova con conteggi uguali.</li></ol><p>I risultati dell&#39;ultima esecuzione e i limiti sono riportati in <code>docs/adr/0022-resilience-details.md</code>.</p><p>Limiti noti del drill: dataset minuscolo (l&#39;RTO reale va misurato con dati veri); PostgreSQL single-node; nessun test di Keycloak; WAL archiviati su volume locale (non su storage remoto); il job di GC dei blob non è stato fatto scattare tra T e il restore (coperto solo dal ragionamento di §4 e dal ripristino da versioni di §5.4).</p>`,31)])])}const b=o(t,[["render",n]]);export{g as __pageData,b as default};
